mapper.select:
select l.id as id, l.admin_id as adminId, coalesce(nullif(l.admin_name, ''), concat('管理员#', l.admin_id)) as adminName, l.operation_type as operationType, as operationTypeDesc, l.target_id as targetId, concat( case l.operation_type when 1 then '商品#' when 2 then '认证#' when 3 then '举报#' else '对象#' end, l.target_id ) as targetSummary, l.action as action, l.detail as detail, l.create_time as createTime from audit_log l
and l.operation_type = #{operationType}
order by l.create_time desc
